DELIMITER $$
CREATE PROCEDURE p_assign_grade(IN p_sno CHAR(8), IN p_cno CHAR(3), IN p_grade INT)
BEGIN
 IF p_grade NOT BETWEEN 0 AND 100 OR NOT EXISTS(SELECT 1 FROM sc x WHERE x.Sno=p_sno AND x.Cno=p_cno) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='不合法的成绩或选课'; END IF; UPDATE sc x SET x.Grade=p_grade WHERE x.Sno=p_sno AND x.Cno=p_cno;
END$$
DELIMITER ;
